<?php
namespace App\Controllers;
use App\Models\ProductModel; use App\Models\CustomerModel; use App\Models\SaleModel;
class Sales extends BaseController
{
    public function new(): string { return view('partials/header',['title'=>'Record Sale']).view('sales/form',['products'=>(new ProductModel())->where('archived_at',null)->where('stock_quantity >',0)->orderBy('name')->findAll(),'customers'=>(new CustomerModel())->orderBy('full_name')->findAll(),'errors'=>[]]).view('partials/footer'); }
    public function create() { if (!$this->validate(['product_id'=>'required|is_natural_no_zero','customer_id'=>'permit_empty|is_natural','quantity'=>'required|is_natural_no_zero'])) return $this->newWithErrors($this->validator->getErrors()); $db=db_connect(); $db->transStart(); $product=(new ProductModel())->where('archived_at',null)->find((int)$this->request->getPost('product_id')); $qty=(int)$this->request->getPost('quantity'); if (!$product || $qty > (int)$product['stock_quantity']) { $db->transRollback(); return $this->newWithErrors(['quantity'=>'The requested quantity exceeds available stock or the product is unavailable.']); } $customer=$this->request->getPost('customer_id'); (new SaleModel())->insert(['product_id'=>$product['id'],'customer_id'=>$customer ? (int)$customer : null,'sold_by'=>(int)session()->get('user.id'),'quantity'=>$qty,'total_price'=>(float)$product['price']*$qty,'created_at'=>date('Y-m-d H:i:s')]); (new ProductModel())->update($product['id'],['stock_quantity'=>(int)$product['stock_quantity']-$qty]); $db->transComplete(); if (!$db->transStatus()) return $this->newWithErrors(['sale'=>'The sale could not be recorded.']); return redirect()->to('/sales')->with('message','Sale recorded successfully.'); }
    public function index(): string { $sales=(new SaleModel())->select('sales.*, products.name product_name, customers.full_name customer_name, users.full_name staff_name')->join('products','products.id=sales.product_id')->join('customers','customers.id=sales.customer_id','left')->join('users','users.id=sales.sold_by')->orderBy('sales.created_at','DESC')->findAll(); return view('partials/header',['title'=>'Sales History']).view('sales/index',['sales'=>$sales]).view('partials/footer'); }
    private function newWithErrors(array $errors): string { return view('partials/header',['title'=>'Record Sale']).view('sales/form',['products'=>(new ProductModel())->where('archived_at',null)->where('stock_quantity >',0)->orderBy('name')->findAll(),'customers'=>(new CustomerModel())->orderBy('full_name')->findAll(),'errors'=>$errors]).view('partials/footer'); }
}
